import { useEffect, useMemo, useState, type ReactNode } from 'react';
import { QueryClient, QueryClientProvider, useQueryClient } from '@tanstack/react-query';
import { ErrorBoundary } from '@/components/error-boundary';
import { Toaster } from '@/components/ui/toaster';
import { TooltipProvider } from '@/components/ui/tooltip';
import { Link, Route, Switch, useLocation, useParams, Router as WouterRouter } from 'wouter';
import {
  Activity, AlertTriangle, ArrowLeft, ArrowRight, Bell, CheckCircle2,
  CircleAlert, ClipboardList, Cpu, Gauge, HardDrive, LayoutDashboard, LogOut,
  Map as MapIcon, Menu, Plus, Radio, RefreshCw, Route as RouteIcon, Server,
  ShieldCheck, SlidersHorizontal, Truck, Users, Wifi, X,
} from 'lucide-react';
import {
  getGetDashboardSummaryQueryKey, getGetDeviceQueryKey, getGetIncidentQueryKey,
  getGetSafetyOverviewQueryKey, getListDevicesQueryKey, getListIncidentsQueryKey,
  getListTripsQueryKey, getListUsersQueryKey, getListVehiclesQueryKey,
  setAuthTokenGetter, useAssignTrip, useClaimIncidentResolution, useCreateTrip,
  useCreateUser, useCreateVehicle, useGetCurrentUser, useGetDashboardSummary,
  useGetDevice, useGetIncident, useGetSafetyOverview, useGetSystemStatus, useHealthCheck, useListDevices, useListIncidents,
  useListTrips, useListUsers, useListVehicles, useLogin, useUnassignTrip,
  useUpdateVehicleSpeedLimit,
} from '@workspace/api-client-react';
import type { Device, Incident, SafetyRow, Trip, User, Vehicle } from '@workspace/api-client-react';

const queryClient = new QueryClient({ defaultOptions: { queries: { staleTime: 12_000, retry: 1 } } });
setAuthTokenGetter(() => localStorage.getItem('mine-vision-token'));

const cn = (...items: Array<string | false | null | undefined>) => items.filter(Boolean).join(' ');
const formatTime = (value?: string | null) => value ? new Date(value).toLocaleString([], { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' }) : '—';
const titleCase = (value?: string | null) => (value ?? '').toLowerCase().replaceAll('_', ' ').replace(/\b\w/g, (l) => l.toUpperCase());
const initials = (name: string) => name.split(' ').map((x) => x[0]).slice(0, 2).join('').toUpperCase();

function Badge({ children, tone = 'neutral' }: { children: ReactNode; tone?: 'good' | 'warn' | 'critical' | 'neutral' | 'teal' }) {
  return <span className={cn('inline-flex items-center gap-1.5 rounded-sm border px-2 py-1 text-[10px] font-semibold uppercase tracking-[.13em]', tone === 'good' && 'border-emerald-700/20 bg-emerald-50 text-emerald-700', tone === 'warn' && 'border-amber-700/20 bg-amber-50 text-amber-800', tone === 'critical' && 'border-red-700/20 bg-red-50 text-red-700', tone === 'teal' && 'border-teal-700/20 bg-teal-50 text-teal-800', tone === 'neutral' && 'border-border bg-secondary text-muted-foreground')}>{children}</span>;
}
function statusTone(status?: string) {
  if (!status) return 'neutral' as const;
  if (['CONNECTED', 'RUNNING', 'REGISTERED', 'SAFE', 'ASSIGNED'].includes(status)) return 'good' as const;
  if (['IDLE', 'WAITING_FOR_CONNECTION', 'PROVISIONING', 'LOW', 'MEDIUM'].includes(status)) return 'warn' as const;
  if (['CRITICAL', 'ERROR', 'CONNECTION_LOST', 'UNSAFE', 'HIGH'].includes(status)) return 'critical' as const;
  return 'neutral' as const;
}
function PageTitle({ eyebrow, title, detail, action }: { eyebrow: string; title: string; detail: string; action?: ReactNode }) {
  return <div className="mb-7 flex flex-col justify-between gap-4 md:flex-row md:items-end">
    <div><p className="mono mb-2 text-[10px] font-semibold uppercase tracking-[.2em] text-primary">{eyebrow}</p><h1 className="condensed text-4xl font-semibold uppercase tracking-tight text-foreground md:text-5xl">{title}</h1><p className="mt-2 max-w-2xl text-sm text-muted-foreground">{detail}</p></div>
    {action}
  </div>;
}
function StatCard({ label, value, detail, icon: Icon, tone = 'teal' }: { label: string; value: ReactNode; detail: string; icon: typeof Activity; tone?: 'teal' | 'amber' | 'red' | 'green' }) {
  return <div className="relative overflow-hidden rounded-md border border-card-border bg-card p-5 shadow-[var(--shadow-sm)]">
    <div className={cn('absolute right-0 top-0 h-1 w-20', tone === 'amber' && 'bg-accent', tone === 'red' && 'bg-destructive', tone === 'green' && 'bg-emerald-600', tone === 'teal' && 'bg-primary')} />
    <div className="mb-5 flex items-start justify-between"><p className="text-[11px] font-semibold uppercase tracking-[.14em] text-muted-foreground">{label}</p><Icon className={cn('h-4 w-4', tone === 'amber' ? 'text-accent' : tone === 'red' ? 'text-destructive' : tone === 'green' ? 'text-emerald-600' : 'text-primary')} /></div>
    <div className="condensed text-4xl font-semibold leading-none">{value}</div><p className="mt-2 text-xs text-muted-foreground">{detail}</p>
  </div>;
}
function SkeletonRows({ count = 4 }: { count?: number }) { return <div className="space-y-3">{Array.from({ length: count }).map((_, i) => <div key={i} className="h-14 animate-pulse rounded bg-secondary" />)}</div>; }
function ErrorState({ message = 'Could not load this operational view.', retry }: { message?: string; retry?: () => void }) { return <div className="flex min-h-48 flex-col items-center justify-center rounded-md border border-dashed border-destructive/30 bg-red-50/40 p-8 text-center"><CircleAlert className="mb-3 h-7 w-7 text-destructive" /><p className="text-sm font-semibold">{message}</p>{retry && <button data-testid="button-retry" onClick={retry} className="mt-4 inline-flex items-center gap-2 rounded border border-destructive/30 px-3 py-2 text-xs font-semibold text-destructive"><RefreshCw className="h-3.5 w-3.5" /> Retry</button>}</div>; }
function EmptyState({ icon: Icon = ClipboardList, title, detail, action }: { icon?: typeof ClipboardList; title: string; detail: string; action?: ReactNode }) { return <div className="flex min-h-48 flex-col items-center justify-center rounded-md border border-dashed border-border bg-card/60 p-8 text-center"><Icon className="mb-3 h-7 w-7 text-muted-foreground" /><h3 className="text-sm font-semibold">{title}</h3><p className="mt-1 max-w-sm text-xs text-muted-foreground">{detail}</p>{action && <div className="mt-4">{action}</div>}</div>; }
function DataTable({ children }: { children: ReactNode }) { return <div className="overflow-x-auto rounded-md border border-card-border bg-card shadow-[var(--shadow-sm)]"><table className="w-full min-w-[720px] text-left text-sm">{children}</table></div>; }
function Section({ title, meta, children, className }: { title: string; meta?: ReactNode; children: ReactNode; className?: string }) { return <section className={cn('rounded-md border border-card-border bg-card shadow-[var(--shadow-sm)]', className)}><div className="flex items-center justify-between border-b border-border px-5 py-4"><h2 className="condensed text-xl font-semibold uppercase tracking-wide">{title}</h2>{meta}</div><div className="p-5">{children}</div></section>; }

const adminNav = [{ href: '/admin', label: 'Overview', icon: LayoutDashboard }, { href: '/admin/vehicles', label: 'Vehicles', icon: Truck }, { href: '/admin/hardware', label: 'Hardware', icon: Cpu }, { href: '/admin/users', label: 'Users', icon: Users }, { href: '/admin/incidents', label: 'Incidents', icon: AlertTriangle }, { href: '/admin/system-status', label: 'System status', icon: Activity }];
const controlNav = [{ href: '/control-room', label: 'Operations', icon: Activity }, { href: '/control-room/fleet', label: 'Fleet manager', icon: Truck }, { href: '/control-room/live-monitoring', label: 'Live monitoring', icon: Radio }, { href: '/control-room/map', label: 'Live map', icon: MapIcon }, { href: '/control-room/incidents', label: 'Incidents', icon: AlertTriangle }, { href: '/control-room/safety', label: 'Safety', icon: ShieldCheck }];

function AppShell({ user, children }: { user: User; children: ReactNode }) {
  const [open, setOpen] = useState(false); const [, setLocation] = useLocation();
  const isAdmin = user.role === 'ADMIN'; const nav = isAdmin ? adminNav : controlNav;
  const signOut = () => { localStorage.removeItem('mine-vision-token'); queryClient.clear(); setLocation('/login'); };
  useRealtime();
  return <div className="min-h-[100dvh] bg-background">
    <aside className={cn('fixed inset-y-0 left-0 z-30 flex w-[248px] flex-col bg-sidebar text-sidebar-foreground transition-transform duration-200 md:translate-x-0', open ? 'translate-x-0' : '-translate-x-full')}>
      <div className="scanline border-b border-sidebar-border px-5 py-5"><div className="flex items-center gap-3"><div className="grid h-9 w-9 place-items-center rounded-sm bg-sidebar-primary text-sidebar-primary-foreground"><span className="condensed text-xl font-bold">MV</span></div><div><p className="condensed text-xl font-semibold uppercase tracking-wider">Mine Vision-X</p><p className="mono text-[9px] uppercase tracking-[.18em] text-sidebar-foreground/55">Operations network</p></div></div></div>
      <div className="px-4 pt-7"><p className="mono px-2 text-[9px] uppercase tracking-[.2em] text-sidebar-foreground/45">{isAdmin ? 'Administration' : 'Control room'}</p><nav className="mt-3 space-y-1">{nav.map(({ href, label, icon: Icon }) => <NavItem key={href} href={href} label={label} icon={Icon} />)}</nav>{!isAdmin && <><p className="mono mt-8 px-2 text-[9px] uppercase tracking-[.2em] text-sidebar-foreground/45">Fleet actions</p><nav className="mt-3 space-y-1"><NavItem href="/control-room/fleet/vehicles" label="Vehicle status" icon={Radio} /><NavItem href="/control-room/fleet/speed-limits" label="Speed limits" icon={SlidersHorizontal} /><NavItem href="/control-room/fleet/trips" label="Trips" icon={RouteIcon} /></nav></>}</div>
      <div className="mt-auto border-t border-sidebar-border p-4"><div className="mb-3 flex items-center gap-3 rounded bg-sidebar-accent p-3"><div className="grid h-8 w-8 place-items-center rounded-full bg-sidebar-primary text-xs font-bold text-sidebar-primary-foreground">{initials(user.displayName)}</div><div className="min-w-0"><p className="truncate text-xs font-semibold">{user.displayName}</p><p className="mono text-[9px] uppercase tracking-wider text-sidebar-foreground/55">{titleCase(user.role)}</p></div></div><button data-testid="button-sign-out" onClick={signOut} className="flex w-full items-center gap-2 rounded px-3 py-2 text-xs font-semibold text-sidebar-foreground/70 hover:bg-sidebar-accent hover:text-sidebar-foreground"><LogOut className="h-3.5 w-3.5" /> Sign out</button></div>
    </aside>
    <div className="md:pl-[248px]"><header className="sticky top-0 z-20 flex h-16 items-center justify-between border-b border-border bg-background/95 px-4 backdrop-blur md:px-8"><div className="flex items-center gap-3"><button data-testid="button-toggle-menu" onClick={() => setOpen(!open)} className="rounded p-2 hover:bg-secondary md:hidden"><Menu className="h-5 w-5" /></button><div className="hidden items-center gap-2 text-xs text-muted-foreground md:flex"><span className="h-2 w-2 rounded-full bg-emerald-500" /> Telemetry link active</div><div className="mono text-[10px] uppercase tracking-[.17em] text-muted-foreground md:hidden">MV-X / {isAdmin ? 'ADMIN' : 'OPS'}</div></div><div className="flex items-center gap-5"><div className="hidden text-right sm:block"><p className="text-xs font-semibold">{user.displayName}</p><p className="mono text-[9px] uppercase tracking-wider text-muted-foreground">{titleCase(user.role)}</p></div><div className="grid h-9 w-9 place-items-center rounded-full border border-border bg-card text-xs font-bold text-primary">{initials(user.displayName)}</div></div></header><main className="grid-texture min-h-[calc(100dvh-4rem)] px-4 py-7 md:px-8 lg:px-10"><div className="mx-auto max-w-[1500px] fade-up">{children}</div></main></div>
  </div>;
}
function NavItem({ href, label, icon: Icon }: { href: string; label: string; icon: typeof Activity }) { const [location] = useLocation(); const active = location === href || (href !== '/admin' && href !== '/control-room' && location.startsWith(href)); return <Link data-testid={`link-${label.toLowerCase().replaceAll(' ', '-')}`} href={href} className={cn('flex items-center gap-3 rounded px-3 py-2.5 text-sm font-medium text-sidebar-foreground/65 hover:bg-sidebar-accent hover:text-sidebar-foreground', active && 'bg-sidebar-accent text-sidebar-foreground shadow-[inset_3px_0_0_hsl(var(--sidebar-primary))]')}><Icon className="h-4 w-4" /><span>{label}</span></Link>; }
function useRealtime() { const qc = useQueryClient(); useEffect(() => { let socket: WebSocket | undefined; let timer: ReturnType<typeof setTimeout>; let stopped = false; const connect = () => { if (stopped) return; const protocol = location.protocol === 'https:' ? 'wss:' : 'ws:'; socket = new WebSocket(`${protocol}//${location.host}/ws`); socket.onmessage = () => { [getGetDashboardSummaryQueryKey(), getListVehiclesQueryKey(), getListDevicesQueryKey(), getListIncidentsQueryKey(), getListTripsQueryKey(), getGetSafetyOverviewQueryKey()].forEach((key) => qc.invalidateQueries({ queryKey: key })); }; socket.onclose = () => { if (!stopped) timer = setTimeout(connect, 2500); }; }; connect(); return () => { stopped = true; clearTimeout(timer); socket?.close(); }; }, [qc]); }

function Login() {
  const [, setLocation] = useLocation(); const login = useLogin(); const [role, setRole] = useState<'ADMIN' | 'CONTROL_ROOM'>('CONTROL_ROOM'); const [username, setUsername] = useState(''); const [password, setPassword] = useState('');
  const submit = (e: React.FormEvent) => { e.preventDefault(); login.mutate({ data: { username, password, role } }, { onSuccess: (session) => { localStorage.setItem('mine-vision-token', session.accessToken); setLocation(session.user.role === 'ADMIN' ? '/admin' : '/control-room'); } }); };
   return <div className="grid min-h-[100dvh] lg:grid-cols-[1.05fr_.95fr]"><div className="relative hidden overflow-hidden bg-sidebar p-12 text-sidebar-foreground lg:flex lg:flex-col lg:justify-between"><div className="absolute inset-0 opacity-30" style={{ backgroundImage: 'radial-gradient(circle at 70% 25%, hsl(38 89% 55% / .22), transparent 25%), linear-gradient(120deg, transparent 60%, hsl(181 48% 27% / .4))' }} /><div className="relative"><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-sm bg-sidebar-primary text-sidebar-primary-foreground"><span className="condensed text-2xl font-bold">MV</span></div><span className="condensed text-2xl font-semibold uppercase tracking-wider">Mine Vision-X</span></div><div className="mt-28 max-w-lg"><p className="mono text-[10px] uppercase tracking-[.24em] text-sidebar-primary">Authenticated operations platform</p><h1 className="condensed mt-5 text-7xl font-semibold uppercase leading-[.88] tracking-tight">See the<br /><span className="text-sidebar-primary">shift</span><br />clearly.</h1><p className="mt-7 max-w-md text-sm leading-6 text-sidebar-foreground/65">One authoritative view of people, machines, and conditions below the surface. Built for the moments where clarity matters most.</p></div></div><div className="relative flex items-center justify-between border-t border-sidebar-border pt-5"><span className="mono text-[9px] uppercase tracking-[.16em] text-sidebar-foreground/45">North sector / secure node</span><span className="flex items-center gap-2 text-xs text-sidebar-foreground/70"><span className="h-2 w-2 rounded-full bg-sidebar-primary" /> System ready</span></div></div><div className="flex items-center justify-center bg-background px-6 py-12"><form onSubmit={submit} className="w-full max-w-[390px]"><div className="mb-10 lg:hidden"><div className="flex items-center gap-3"><div className="grid h-9 w-9 place-items-center rounded-sm bg-primary text-primary-foreground"><span className="condensed text-xl font-bold">MV</span></div><span className="condensed text-xl font-semibold uppercase tracking-wider">Mine Vision-X</span></div></div><p className="mono text-[10px] font-semibold uppercase tracking-[.2em] text-primary">Secure sign-in</p><h2 className="condensed mt-3 text-5xl font-semibold uppercase tracking-tight">Welcome back.</h2><p className="mt-3 text-sm text-muted-foreground">Use your operations credentials to continue.</p><div className="mt-9"><p className="mb-2 text-xs font-semibold uppercase tracking-wider">Workspace</p><div className="grid grid-cols-2 gap-2">{(['CONTROL_ROOM', 'ADMIN'] as const).map((item) => <button type="button" key={item} data-testid={`button-role-${item.toLowerCase()}`} onClick={() => setRole(item)} className={cn('rounded border px-3 py-3 text-left', role === item ? 'border-primary bg-primary/5 text-primary' : 'border-border bg-card text-muted-foreground')}><span className="block text-xs font-bold">{item === 'ADMIN' ? 'Admin' : 'Control Room'}</span><span className="mt-1 block text-[10px]">{item === 'ADMIN' ? 'Manage the network' : 'Run the shift'}</span></button>)}</div></div><label className="mt-7 block text-xs font-semibold uppercase tracking-wider">Username<input data-testid="input-username" value={username} onChange={(e) => setUsername(e.target.value)} required className="mt-2 h-11 w-full rounded border border-input bg-card px-3 text-sm outline-none focus:border-primary focus:ring-2 focus:ring-primary/10" autoComplete="username" /></label><label className="mt-5 block text-xs font-semibold uppercase tracking-wider">Password<input data-testid="input-password" type="password" value={password} onChange={(e) => setPassword(e.target.value)} required className="mt-2 h-11 w-full rounded border border-input bg-card px-3 text-sm outline-none focus:border-primary focus:ring-2 focus:ring-primary/10" autoComplete="current-password" /></label>{role === 'ADMIN' && <p className="mt-4 rounded border border-accent/30 bg-accent/10 px-3 py-2 text-[10px] leading-4 text-accent-foreground">DEVELOPMENT ONLY — WebAuthn / Windows Hello is not configured in this environment.</p>}{login.isError && <p data-testid="status-login-error" className="mt-4 rounded border border-destructive/30 bg-red-50 px-3 py-2 text-xs text-destructive">Sign-in was not accepted. Check your credentials and try again.</p>}<button data-testid="button-sign-in" disabled={login.isPending} className="mt-7 flex h-11 w-full items-center justify-center gap-2 rounded bg-primary text-sm font-semibold text-primary-foreground hover:bg-primary/90 disabled:opacity-60">{login.isPending ? 'Authenticating…' : `Continue as ${role === 'ADMIN' ? 'Admin' : 'Control Room'}`}<ArrowRight className="h-4 w-4" /></button><p className="mono mt-8 text-center text-[9px] uppercase tracking-[.15em] text-muted-foreground">All activity is logged · MVX secure access</p></form></div></div>;
}

function AuthGate({ children }: { children: ReactNode }) { const [, setLocation] = useLocation(); const userQuery = useGetCurrentUser(); useEffect(() => { if (userQuery.isError) setLocation('/login'); }, [userQuery.isError, setLocation]); if (userQuery.isLoading) return <div className="grid min-h-[100dvh] place-items-center bg-background"><div className="w-64 space-y-3"><div className="h-8 animate-pulse rounded bg-secondary" /><div className="h-3 animate-pulse rounded bg-secondary" /><div className="h-3 animate-pulse rounded bg-secondary" /></div></div>; if (!userQuery.data) return null; return <AppShell user={userQuery.data}>{children}</AppShell>; }
function AdminOverview() {
  const summary = useGetDashboardSummary(); const vehicles = useListVehicles(); const devices = useListDevices(); const health = useHealthCheck(); const s = summary.data;
  return <><PageTitle eyebrow="Admin / network overview" title="System overview" detail="A high-level read of the authenticated mine network, registration funnel, and operational readiness." action={<div className="flex items-center gap-2 rounded border border-border bg-card px-3 py-2 text-xs"><span className={cn('h-2 w-2 rounded-full', health.data?.status === 'ok' ? 'bg-emerald-500' : health.isError ? 'bg-amber-500' : 'bg-primary')} /> API {health.data?.status ?? (health.isLoading ? 'checking' : 'reachable')}</div>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{summary.isLoading ? Array.from({ length: 4 }).map((_, i) => <div key={i} className="h-32 animate-pulse rounded-md bg-secondary" />) : <><StatCard label="Active vehicles" value={s?.totalActiveVehicles ?? '—'} detail={`${s?.connectedVehicles ?? 0} connected to telemetry`} icon={Truck} /><StatCard label="Running now" value={s?.runningVehicles ?? '—'} detail={`${s?.idleVehicles ?? 0} currently idle`} icon={Activity} tone="green" /><StatCard label="Active incidents" value={s?.activeIncidents ?? '—'} detail={`${s?.criticalAlerts ?? 0} critical attention`} icon={AlertTriangle} tone={s?.criticalAlerts ? 'red' : 'amber'} /><StatCard label="Completed cycles" value={s?.completedCycles ?? '—'} detail={`${s?.trips ?? 0} trips in system`} icon={RouteIcon} tone="amber" /></>}</div><div className="mt-6 grid gap-6 xl:grid-cols-[1.1fr_.9fr]"><Section title="Registration funnel" meta={<Link href="/admin/vehicles" className="text-xs font-semibold text-primary">Manage vehicles <ArrowRight className="ml-1 inline h-3.5 w-3.5" /></Link>}><div className="space-y-5">{['REGISTERED', 'PROVISIONING', 'WAITING_FOR_CONNECTION'].map((status) => { const count = (vehicles.data ?? []).filter((v) => v.registrationStatus === status).length; const total = Math.max(vehicles.data?.length ?? 0, 1); return <div key={status}><div className="mb-2 flex justify-between text-xs"><span className="font-semibold">{titleCase(status)}</span><span className="mono text-muted-foreground">{count.toString().padStart(2, '0')} / {total.toString().padStart(2, '0')}</span></div><div className="h-2 overflow-hidden rounded bg-secondary"><div className={cn('h-full rounded', status === 'REGISTERED' ? 'bg-primary' : status === 'PROVISIONING' ? 'bg-accent' : 'bg-muted-foreground/50')} style={{ width: `${Math.max((count / total) * 100, count ? 8 : 0)}%` }} /></div></div> })}</div></Section><Section title="Hardware posture" meta={<Link href="/admin/hardware" className="text-xs font-semibold text-primary">Inspect fleet <ArrowRight className="ml-1 inline h-3.5 w-3.5" /></Link>}>{devices.isLoading ? <SkeletonRows count={3} /> : devices.isError ? <ErrorState retry={devices.refetch} /> : !(devices.data ?? []).length ? <EmptyState icon={Cpu} title="No devices provisioned" detail="Provisioned Raspberry Pi nodes will appear here." /> : <div className="space-y-4">{(devices.data ?? []).slice(0, 4).map((d) => <div key={d.id} className="flex items-center justify-between border-b border-border pb-3 last:border-0 last:pb-0"><div className="flex items-center gap-3"><div className="grid h-8 w-8 place-items-center rounded bg-secondary"><Cpu className="h-4 w-4 text-primary" /></div><div><p className="mono text-xs font-semibold">{d.identifier}</p><p className="text-[11px] text-muted-foreground">{formatTime(d.lastSeen)}</p></div></div><Badge tone={statusTone(d.connectionStatus)}>{titleCase(d.connectionStatus)}</Badge></div>)}</div>}</Section></div></>;
}

function VehicleRegistration() {
  const vehicles = useListVehicles(); const create = useCreateVehicle(); const [show, setShow] = useState(false); const [form, setForm] = useState({ id: '', name: '', type: '', deviceIdentifier: '', deviceSecret: '' }); const qc = useQueryClient();
  const submit = (e: React.FormEvent) => { e.preventDefault(); create.mutate({ data: form }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getListVehiclesQueryKey() }); setForm({ id: '', name: '', type: '', deviceIdentifier: '', deviceSecret: '' }); setShow(false); } }); };
  return <><PageTitle eyebrow="Admin / asset registry" title="Vehicles" detail="Register the physical assets that telemetry can authenticate. Registration provisions the device identity in one step." action={<button data-testid="button-open-register-vehicle" onClick={() => setShow(true)} className="inline-flex items-center justify-center gap-2 rounded bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground"><Plus className="h-4 w-4" /> Register vehicle</button>} />{show && <div className="mb-6 rounded-md border border-primary/30 bg-primary/[.04] p-5"><div className="mb-5 flex items-center justify-between"><div><h2 className="condensed text-2xl font-semibold uppercase">New registration</h2><p className="text-xs text-muted-foreground">Credentials are held by the backend and used by the Pi agent.</p></div><button data-testid="button-close-register-vehicle" onClick={() => setShow(false)} className="rounded p-2 hover:bg-secondary"><X className="h-4 w-4" /></button></div><form onSubmit={submit} className="grid gap-4 sm:grid-cols-2 lg:grid-cols-5"><Field label="Vehicle ID" value={form.id} onChange={(v) => setForm({ ...form, id: v })} required placeholder="TRK-021" testId="input-vehicle-id" /><Field label="Display name" value={form.name} onChange={(v) => setForm({ ...form, name: v })} required placeholder="Hauler 21" testId="input-vehicle-name" /><Field label="Vehicle type" value={form.type} onChange={(v) => setForm({ ...form, type: v })} required placeholder="Haul truck" testId="input-vehicle-type" /><Field label="Device identifier" value={form.deviceIdentifier} onChange={(v) => setForm({ ...form, deviceIdentifier: v })} required placeholder="pi-north-021" testId="input-device-identifier" /><Field label="Device secret" value={form.deviceSecret} onChange={(v) => setForm({ ...form, deviceSecret: v })} required placeholder="••••••••" testId="input-device-secret" /><button data-testid="button-submit-register-vehicle" disabled={create.isPending} className="rounded bg-accent px-3 py-2 text-sm font-semibold text-accent-foreground sm:col-span-2 lg:col-span-5 lg:justify-self-end">{create.isPending ? 'Provisioning…' : 'Create registration'}</button></form>{create.isError && <p className="mt-3 text-xs text-destructive">Registration failed. Verify the asset identity and try again.</p>}</div>}<Section title="Registered vehicles" meta={<span className="mono text-[10px] uppercase tracking-wider text-muted-foreground">{vehicles.data?.length ?? 0} assets</span>}>{vehicles.isLoading ? <SkeletonRows /> : vehicles.isError ? <ErrorState retry={vehicles.refetch} /> : !(vehicles.data ?? []).length ? <EmptyState icon={Truck} title="No vehicles registered" detail="Start with a vehicle and its authenticated Raspberry Pi identity." action={<button data-testid="button-empty-register-vehicle" onClick={() => setShow(true)} className="rounded bg-primary px-3 py-2 text-xs font-semibold text-primary-foreground">Register first vehicle</button>} /> : <DataTable><thead><tr className="border-b border-border bg-secondary/60 text-[10px] uppercase tracking-[.14em] text-muted-foreground"><th className="px-5 py-3">Vehicle</th><th className="px-5 py-3">Type</th><th className="px-5 py-3">Registration</th><th className="px-5 py-3">Connection</th><th className="px-5 py-3">Last update</th></tr></thead><tbody>{(vehicles.data ?? []).map((v) => <tr key={v.id} data-testid={`row-vehicle-${v.id}`} className="border-b border-border last:border-0 hover:bg-secondary/35"><td className="px-5 py-4"><p className="font-semibold">{v.name}</p><p className="mono mt-1 text-[10px] text-muted-foreground">{v.id}</p></td><td className="px-5 py-4 text-muted-foreground">{v.type}</td><td className="px-5 py-4"><Badge tone={statusTone(v.registrationStatus)}>{titleCase(v.registrationStatus)}</Badge></td><td className="px-5 py-4"><Badge tone={statusTone(v.connectionStatus)}><span className="h-1.5 w-1.5 rounded-full bg-current" />{titleCase(v.connectionStatus)}</Badge></td><td className="mono px-5 py-4 text-xs text-muted-foreground">{formatTime(v.updatedAt)}</td></tr>)}</tbody></DataTable>}</Section></>;
}
function Field({ label, value, onChange, placeholder, required, type = 'text', testId }: { label: string; value: string; onChange: (value: string) => void; placeholder?: string; required?: boolean; type?: string; testId: string }) { return <label className="block text-[10px] font-semibold uppercase tracking-[.13em] text-muted-foreground">{label}<input data-testid={testId} required={required} type={type} value={value} placeholder={placeholder} onChange={(e) => onChange(e.target.value)} className="mt-2 h-10 w-full rounded border border-input bg-card px-3 text-sm font-normal normal-case tracking-normal text-foreground outline-none focus:border-primary focus:ring-2 focus:ring-primary/10" /></label>; }

function Hardware() {
  const devices = useListDevices(); const [selected, setSelected] = useState<string | null>(null); const detail = useGetDevice(selected ?? '', { query: { enabled: !!selected, queryKey: getGetDeviceQueryKey(selected ?? '') } });
  return <><PageTitle eyebrow="Admin / infrastructure" title="Hardware diagnostics" detail="Provisioned Raspberry Pi nodes, connection state, and backend-reported health checks." /><div className="grid gap-6 xl:grid-cols-[1fr_360px]"><Section title="Provisioned nodes" meta={<button data-testid="button-refresh-devices" onClick={() => devices.refetch()} className="rounded p-2 text-muted-foreground hover:bg-secondary"><RefreshCw className="h-4 w-4" /></button>}>{devices.isLoading ? <SkeletonRows count={5} /> : devices.isError ? <ErrorState retry={devices.refetch} /> : !(devices.data ?? []).length ? <EmptyState icon={Cpu} title="No provisioned hardware" detail="Vehicle registrations with device identities will appear in this diagnostic view." /> : <div className="space-y-2">{(devices.data ?? []).map((d) => <button data-testid={`button-device-${d.id}`} onClick={() => setSelected(d.id)} key={d.id} className={cn('flex w-full items-center justify-between rounded border p-4 text-left hover:bg-secondary/40', selected === d.id && 'border-primary bg-primary/[.04]')}><div className="flex items-center gap-3"><div className="grid h-9 w-9 place-items-center rounded bg-secondary"><Server className="h-4 w-4 text-primary" /></div><div><p className="mono text-xs font-semibold">{d.identifier}</p><p className="mt-1 text-xs text-muted-foreground">Vehicle {d.vehicleId}</p></div></div><div className="text-right"><Badge tone={statusTone(d.connectionStatus)}>{titleCase(d.connectionStatus)}</Badge><p className="mono mt-2 text-[9px] text-muted-foreground">{formatTime(d.lastSeen)}</p></div></button>)}</div>}</Section><Section title="Node detail" meta={selected && <button data-testid="button-close-device-detail" onClick={() => setSelected(null)} className="rounded p-1 hover:bg-secondary"><X className="h-4 w-4" /></button>}>{!selected ? <EmptyState icon={HardDrive} title="Select a node" detail="Choose a provisioned node to inspect its latest backend health signals." /> : detail.isLoading ? <SkeletonRows count={4} /> : detail.isError ? <ErrorState retry={detail.refetch} /> : detail.data ? <DeviceDetail device={detail.data} /> : null}</Section></div></>;
}
function DeviceDetail({ device }: { device: Device }) { return <div className="space-y-5"><div><p className="mono text-lg font-semibold">{device.identifier}</p><p className="mt-1 text-xs text-muted-foreground">Last seen {formatTime(device.lastSeen)}</p></div><div className="space-y-3">{[['GPS signal', device.gpsHealthy], ['Sensor bus', device.sensorHealthy], ['Camera stream', device.cameraHealthy]].map(([label, healthy]) => <div key={String(label)} className="flex items-center justify-between border-b border-border pb-3"><span className="text-sm">{String(label)}</span><span className={cn('flex items-center gap-2 text-xs font-semibold', healthy ? 'text-emerald-700' : 'text-destructive')}><span className={cn('h-2 w-2 rounded-full', healthy ? 'bg-emerald-500' : 'bg-destructive')} />{healthy ? 'Healthy' : 'Fault detected'}</span></div>)}</div></div>; }

function UsersPage() {
  const users = useListUsers(); const create = useCreateUser(); const qc = useQueryClient(); const [show, setShow] = useState(false); const [form, setForm] = useState({ username: '', displayName: '', password: '', role: 'CONTROL_ROOM' as 'ADMIN' | 'CONTROL_ROOM' });
  const submit = (e: React.FormEvent) => { e.preventDefault(); create.mutate({ data: form }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getListUsersQueryKey() }); setShow(false); setForm({ username: '', displayName: '', password: '', role: 'CONTROL_ROOM' }); } }); };
  return <><PageTitle eyebrow="Admin / access control" title="Software users" detail="Create the people who can access the administrative and control room surfaces." action={<button data-testid="button-open-create-user" onClick={() => setShow(true)} className="inline-flex items-center gap-2 rounded bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground"><Plus className="h-4 w-4" /> Create user</button>} />{show && <div className="mb-6 rounded-md border border-primary/30 bg-primary/[.04] p-5"><div className="mb-5 flex justify-between"><div><h2 className="condensed text-2xl font-semibold uppercase">Create access</h2><p className="text-xs text-muted-foreground">Roles determine the first workspace after sign-in.</p></div><button data-testid="button-close-create-user" onClick={() => setShow(false)}><X className="h-4 w-4" /></button></div><form onSubmit={submit} className="grid gap-4 md:grid-cols-4"><Field label="Username" value={form.username} onChange={(v) => setForm({ ...form, username: v })} required placeholder="m.ortiz" testId="input-new-username" /><Field label="Display name" value={form.displayName} onChange={(v) => setForm({ ...form, displayName: v })} required placeholder="Mara Ortiz" testId="input-new-display-name" /><Field label="Password" type="password" value={form.password} onChange={(v) => setForm({ ...form, password: v })} required placeholder="Minimum 8 characters" testId="input-new-password" /><label className="block text-[10px] font-semibold uppercase tracking-[.13em] text-muted-foreground">Role<select data-testid="select-new-role" value={form.role} onChange={(e) => setForm({ ...form, role: e.target.value as 'ADMIN' | 'CONTROL_ROOM' })} className="mt-2 h-10 w-full rounded border border-input bg-card px-3 text-sm font-normal tracking-normal outline-none"><option value="CONTROL_ROOM">Control Room</option><option value="ADMIN">Admin</option></select></label><button data-testid="button-submit-create-user" disabled={create.isPending} className="rounded bg-accent px-3 py-2 text-sm font-semibold text-accent-foreground md:col-span-4 md:justify-self-end">{create.isPending ? 'Creating…' : 'Create user'}</button></form></div>}<Section title="Current users" meta={<span className="mono text-[10px] uppercase tracking-wider text-muted-foreground">{users.data?.length ?? 0} accounts</span>}>{users.isLoading ? <SkeletonRows /> : users.isError ? <ErrorState retry={users.refetch} /> : !(users.data ?? []).length ? <EmptyState icon={Users} title="No users found" detail="Create an account to open the operations network." /> : <DataTable><thead><tr className="border-b border-border bg-secondary/60 text-[10px] uppercase tracking-[.14em] text-muted-foreground"><th className="px-5 py-3">Identity</th><th className="px-5 py-3">Username</th><th className="px-5 py-3">Role</th><th className="px-5 py-3">Account ID</th></tr></thead><tbody>{(users.data ?? []).map((u) => <tr key={u.id} data-testid={`row-user-${u.id}`} className="border-b border-border last:border-0"><td className="px-5 py-4 font-semibold">{u.displayName}</td><td className="px-5 py-4 mono text-xs text-muted-foreground">{u.username}</td><td className="px-5 py-4"><Badge tone={u.role === 'ADMIN' ? 'teal' : 'neutral'}>{titleCase(u.role)}</Badge></td><td className="px-5 py-4 mono text-[10px] text-muted-foreground">{u.id}</td></tr>)}</tbody></DataTable>}</Section></>;
}

function ControlDashboard() {
  const summary = useGetDashboardSummary(); const incidents = useListIncidents(); const vehicles = useListVehicles(); const s = summary.data; const active = (incidents.data ?? []).filter((x) => x.status === 'ACTIVE').slice(0, 4);
  return <><PageTitle eyebrow="Control room / current shift" title="Operations pulse" detail="Live operational posture from authenticated vehicle telemetry. Changes arrive as the backend accepts them." action={<Link href="/control-room/map" className="inline-flex items-center gap-2 rounded border border-primary/30 bg-primary/[.05] px-4 py-2.5 text-sm font-semibold text-primary"><MapIcon className="h-4 w-4" /> Open live map</Link>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{summary.isLoading ? Array.from({ length: 4 }).map((_, i) => <div key={i} className="h-32 animate-pulse rounded-md bg-secondary" />) : <><StatCard label="Connected fleet" value={s?.connectedVehicles ?? '—'} detail={`${s?.totalActiveVehicles ?? 0} active vehicles`} icon={Wifi} /><StatCard label="Running" value={s?.runningVehicles ?? '—'} detail={`${s?.idleVehicles ?? 0} idle vehicles`} icon={Activity} tone="green" /><StatCard label="Safety incidents" value={s?.activeIncidents ?? '—'} detail={`${s?.criticalAlerts ?? 0} critical`} icon={Bell} tone={s?.criticalAlerts ? 'red' : 'amber'} /><StatCard label="Shift cycles" value={s?.completedCycles ?? '—'} detail={`${s?.trips ?? 0} live trips`} icon={Gauge} tone="amber" /></>}</div><div className="mt-6 grid gap-6 xl:grid-cols-[1.4fr_.8fr]"><Section title="Fleet activity" meta={<Link href="/control-room/fleet/vehicles" className="text-xs font-semibold text-primary">View all <ArrowRight className="ml-1 inline h-3.5 w-3.5" /></Link>}><div className="grid gap-3 sm:grid-cols-2">{vehicles.isLoading ? <SkeletonRows count={4} /> : vehicles.isError ? <ErrorState retry={vehicles.refetch} /> : !(vehicles.data ?? []).length ? <div className="sm:col-span-2"><EmptyState icon={Truck} title="No live vehicles" detail="Connected fleet assets will surface here as telemetry is accepted." /></div> : (vehicles.data ?? []).slice(0, 6).map((v) => <VehicleMini key={v.id} vehicle={v} />)}</div></Section><Section title="Attention queue" meta={<Link href="/control-room/incidents" className="text-xs font-semibold text-primary">Incident desk <ArrowRight className="ml-1 inline h-3.5 w-3.5" /></Link>}>{incidents.isLoading ? <SkeletonRows count={3} /> : incidents.isError ? <ErrorState retry={incidents.refetch} /> : !active.length ? <EmptyState icon={ShieldCheck} title="No active incidents" detail="The active queue is clear." /> : <div className="space-y-4">{active.map((i) => <IncidentRow key={i.id} incident={i} />)}</div>}</Section></div></>;
}
function VehicleMini({ vehicle }: { vehicle: Vehicle }) { return <div className="rounded border border-border bg-background/45 p-4"><div className="flex items-start justify-between"><div><p className="font-semibold">{vehicle.name}</p><p className="mono mt-1 text-[10px] text-muted-foreground">{vehicle.id} · {vehicle.type}</p></div><Badge tone={statusTone(vehicle.operationalStatus)}>{titleCase(vehicle.operationalStatus)}</Badge></div><div className="mt-4 flex items-end justify-between"><div><span className="condensed text-3xl font-semibold">{vehicle.speed.toFixed(1)}</span><span className="ml-1 text-xs text-muted-foreground">km/h</span></div><p className="mono text-[10px] text-muted-foreground">limit {vehicle.speedLimit}</p></div></div>; }
function IncidentRow({ incident, onClaim, onInspect }: { incident: Incident; onClaim?: () => void; onInspect?: () => void }) { return <div className="flex gap-3 border-b border-border pb-4 last:border-0 last:pb-0"><div className={cn('mt-1 h-2 w-2 shrink-0 rounded-full', incident.severity === 'CRITICAL' ? 'bg-destructive' : incident.severity === 'HIGH' ? 'bg-accent' : 'bg-primary')} /><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center justify-between gap-2"><p className="text-sm font-semibold">{incident.vehicleName}</p><Badge tone={statusTone(incident.severity)}>{incident.severity}</Badge></div><p className="mt-1 text-xs text-muted-foreground">{incident.message}</p><div className="mt-2 flex items-center justify-between"><span className="mono text-[9px] uppercase tracking-wider text-muted-foreground">{titleCase(incident.type)} · {formatTime(incident.createdAt)}</span><div className="flex items-center gap-3">{onInspect && <button data-testid={`button-inspect-incident-${incident.id}`} onClick={onInspect} className="text-[10px] font-semibold text-muted-foreground hover:text-primary">Inspect</button>}{onClaim && <button data-testid={`button-claim-incident-${incident.id}`} onClick={onClaim} className="text-[10px] font-semibold text-primary hover:underline">Claim resolution</button>}</div></div></div></div>; }

function FleetOverview() { const summary = useGetDashboardSummary(); const trips = useListTrips(); return <><PageTitle eyebrow="Control room / fleet manager" title="Fleet manager" detail="Coordinate vehicle availability and work allocation for the current operation." /><div className="grid gap-4 sm:grid-cols-3"><StatCard label="Vehicles active" value={summary.data?.totalActiveVehicles ?? '—'} detail="Backend-derived count" icon={Truck} /><StatCard label="Current trips" value={summary.data?.trips ?? '—'} detail="Work in the system" icon={RouteIcon} tone="amber" /><StatCard label="Cycles complete" value={summary.data?.completedCycles ?? '—'} detail="Across registered fleet" icon={CheckCircle2} tone="green" /></div><div className="mt-6 grid gap-6 lg:grid-cols-[1fr_360px]"><Section title="Dispatch shortcuts"><div className="grid gap-3 sm:grid-cols-3"><Link href="/control-room/fleet/vehicles" className="rounded border border-border p-4 hover:border-primary"><Truck className="mb-6 h-5 w-5 text-primary" /><p className="text-sm font-semibold">Vehicle status</p><p className="mt-1 text-xs text-muted-foreground">Connection, activity, and limits.</p></Link><Link href="/control-room/fleet/speed-limits" className="rounded border border-border p-4 hover:border-primary"><SlidersHorizontal className="mb-6 h-5 w-5 text-primary" /><p className="text-sm font-semibold">Speed limits</p><p className="mt-1 text-xs text-muted-foreground">Edit backend-enforced limits.</p></Link><Link href="/control-room/fleet/trips" className="rounded border border-border p-4 hover:border-primary"><RouteIcon className="mb-6 h-5 w-5 text-primary" /><p className="text-sm font-semibold">Trip board</p><p className="mt-1 text-xs text-muted-foreground">Create and assign work.</p></Link></div></Section><Section title="Trip allocation">{trips.isLoading ? <SkeletonRows count={3} /> : trips.isError ? <ErrorState retry={trips.refetch} /> : <div className="space-y-3">{(trips.data ?? []).slice(0, 5).map((t) => <div key={t.id} className="flex items-center justify-between border-b border-border pb-3 last:border-0 last:pb-0"><div><p className="text-sm font-semibold">{t.name}</p><p className="text-xs text-muted-foreground">{t.source} → {t.destination}</p></div><Badge tone={statusTone(t.assignmentStatus)}>{titleCase(t.assignmentStatus)}</Badge></div>)}</div>}</Section></div></>; }

function FleetVehicles() { const vehicles = useListVehicles(); return <><PageTitle eyebrow="Control room / fleet manager" title="Vehicle status" detail="A live operational inventory of every registered asset and its enforced speed limit." /><Section title="Fleet inventory" meta={<span className="mono text-[10px] uppercase tracking-wider text-muted-foreground">{vehicles.data?.length ?? 0} vehicles</span>}>{vehicles.isLoading ? <SkeletonRows count={6} /> : vehicles.isError ? <ErrorState retry={vehicles.refetch} /> : !(vehicles.data ?? []).length ? <EmptyState icon={Truck} title="Fleet is empty" detail="No registered vehicles have been returned by the backend." /> : <DataTable><thead><tr className="border-b border-border bg-secondary/60 text-[10px] uppercase tracking-[.14em] text-muted-foreground"><th className="px-5 py-3">Vehicle</th><th className="px-5 py-3">Operational</th><th className="px-5 py-3">Connection</th><th className="px-5 py-3">Speed</th><th className="px-5 py-3">Limit</th><th className="px-5 py-3">Visibility</th></tr></thead><tbody>{(vehicles.data ?? []).map((v) => <tr key={v.id} data-testid={`row-fleet-vehicle-${v.id}`} className="border-b border-border last:border-0"><td className="px-5 py-4"><p className="font-semibold">{v.name}</p><p className="mono text-[10px] text-muted-foreground">{v.id}</p></td><td className="px-5 py-4"><Badge tone={statusTone(v.operationalStatus)}>{titleCase(v.operationalStatus)}</Badge></td><td className="px-5 py-4"><Badge tone={statusTone(v.connectionStatus)}>{titleCase(v.connectionStatus)}</Badge></td><td className="px-5 py-4"><span className="condensed text-2xl font-semibold">{v.speed.toFixed(1)}</span><span className="ml-1 text-xs text-muted-foreground">km/h</span></td><td className="mono px-5 py-4 text-xs">{v.speedLimit} km/h</td><td className="px-5 py-4"><Badge tone={statusTone(v.visibility)}>{titleCase(v.visibility)}</Badge></td></tr>)}</tbody></DataTable>}</Section></>; }

function SpeedLimits() { const vehicles = useListVehicles(); const update = useUpdateVehicleSpeedLimit(); const qc = useQueryClient(); const [values, setValues] = useState<Record<string, string>>({}); const [saved, setSaved] = useState<string | null>(null); const submit = (v: Vehicle) => { const speedLimit = Number(values[v.id] ?? v.speedLimit); if (!Number.isFinite(speedLimit) || speedLimit < 1 || speedLimit > 120) return; update.mutate({ vehicleId: v.id, data: { speedLimit } }, { onSuccess: () => { setSaved(v.id); qc.invalidateQueries({ queryKey: getListVehiclesQueryKey() }); setTimeout(() => setSaved(null), 1800); } }); }; return <><PageTitle eyebrow="Control room / fleet manager" title="Speed limits" detail="Edit the backend speed limit enforced for each vehicle. Changes are authoritative for telemetry evaluation." /><Section title="Enforced limits" meta={<span className="text-xs text-muted-foreground">Range 1–120 km/h</span>}>{vehicles.isLoading ? <SkeletonRows count={6} /> : vehicles.isError ? <ErrorState retry={vehicles.refetch} /> : !(vehicles.data ?? []).length ? <EmptyState icon={SlidersHorizontal} title="No limits to edit" detail="Registered vehicles will appear when available." /> : <div className="space-y-2">{(vehicles.data ?? []).map((v) => <div key={v.id} className="flex flex-col gap-4 rounded border border-border p-4 sm:flex-row sm:items-center sm:justify-between"><div className="flex items-center gap-3"><div className="grid h-9 w-9 place-items-center rounded bg-secondary"><Gauge className="h-4 w-4 text-primary" /></div><div><p className="font-semibold">{v.name}</p><p className="mono text-[10px] text-muted-foreground">{v.id} · current {v.speed.toFixed(1)} km/h</p></div></div><div className="flex items-center gap-2"><div className="relative"><input data-testid={`input-speed-limit-${v.id}`} type="number" min="1" max="120" value={values[v.id] ?? v.speedLimit} onChange={(e) => setValues({ ...values, [v.id]: e.target.value })} className="h-10 w-28 rounded border border-input bg-background px-3 pr-12 text-sm outline-none focus:border-primary" /><span className="pointer-events-none absolute right-3 top-3 text-[10px] text-muted-foreground">km/h</span></div><button data-testid={`button-save-speed-limit-${v.id}`} onClick={() => submit(v)} disabled={update.isPending} className="h-10 rounded bg-primary px-3 text-xs font-semibold text-primary-foreground">{saved === v.id ? 'Saved' : 'Save'}</button></div></div>)}</div>}</Section>{update.isError && <p className="mt-4 text-xs text-destructive">The speed limit could not be updated. The backend rejected the change.</p>}</>; }

function Trips() { const trips = useListTrips(); const vehicles = useListVehicles(); const create = useCreateTrip(); const assign = useAssignTrip(); const unassign = useUnassignTrip(); const qc = useQueryClient(); const [show, setShow] = useState(false); const [form, setForm] = useState({ name: '', source: '', destination: '' }); const invalidate = () => qc.invalidateQueries({ queryKey: getListTripsQueryKey() }); const submit = (e: React.FormEvent) => { e.preventDefault(); create.mutate({ data: form }, { onSuccess: () => { invalidate(); setShow(false); setForm({ name: '', source: '', destination: '' }); } }); }; return <><PageTitle eyebrow="Control room / fleet manager" title="Trips" detail="Create work, assign it to an available vehicle, and release it when the allocation changes." action={<button data-testid="button-open-create-trip" onClick={() => setShow(true)} className="inline-flex items-center gap-2 rounded bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground"><Plus className="h-4 w-4" /> Create trip</button>} />{show && <div className="mb-6 rounded-md border border-primary/30 bg-primary/[.04] p-5"><div className="mb-5 flex justify-between"><div><h2 className="condensed text-2xl font-semibold uppercase">New trip</h2><p className="text-xs text-muted-foreground">The backend will own assignment state and cycle counts.</p></div><button data-testid="button-close-create-trip" onClick={() => setShow(false)}><X className="h-4 w-4" /></button></div><form onSubmit={submit} className="grid gap-4 md:grid-cols-4"><Field label="Trip name" value={form.name} onChange={(v) => setForm({ ...form, name: v })} required placeholder="North face haul" testId="input-trip-name" /><Field label="Source" value={form.source} onChange={(v) => setForm({ ...form, source: v })} required placeholder="Crusher 02" testId="input-trip-source" /><Field label="Destination" value={form.destination} onChange={(v) => setForm({ ...form, destination: v })} required placeholder="Stockpile B" testId="input-trip-destination" /><button data-testid="button-submit-create-trip" disabled={create.isPending} className="rounded bg-accent px-3 py-2 text-sm font-semibold text-accent-foreground">{create.isPending ? 'Creating…' : 'Create trip'}</button></form></div>}<Section title="Trip board" meta={<span className="mono text-[10px] uppercase tracking-wider text-muted-foreground">{trips.data?.length ?? 0} trips</span>}>{trips.isLoading ? <SkeletonRows count={5} /> : trips.isError ? <ErrorState retry={trips.refetch} /> : !(trips.data ?? []).length ? <EmptyState icon={RouteIcon} title="No trips yet" detail="Create a trip to begin allocating work across the fleet." action={<button data-testid="button-empty-create-trip" onClick={() => setShow(true)} className="rounded bg-primary px-3 py-2 text-xs font-semibold text-primary-foreground">Create first trip</button>} /> : <DataTable><thead><tr className="border-b border-border bg-secondary/60 text-[10px] uppercase tracking-[.14em] text-muted-foreground"><th className="px-5 py-3">Trip</th><th className="px-5 py-3">Route</th><th className="px-5 py-3">Assignment</th><th className="px-5 py-3">Cycles</th><th className="px-5 py-3">Action</th></tr></thead><tbody>{(trips.data ?? []).map((t) => <tr key={t.id} className="border-b border-border last:border-0"><td className="px-5 py-4"><p className="font-semibold">{t.name}</p><p className="mono text-[10px] text-muted-foreground">{t.id}</p></td><td className="px-5 py-4 text-muted-foreground">{t.source} <ArrowRight className="mx-1 inline h-3.5 w-3.5" /> {t.destination}</td><td className="px-5 py-4">{t.vehicleName ? <><p className="text-xs font-semibold">{t.vehicleName}</p><Badge tone="good">Assigned</Badge></> : <Badge>Free</Badge>}</td><td className="mono px-5 py-4 text-xs">{t.completedCycles}</td><td className="px-5 py-4">{t.assignmentStatus === 'ASSIGNED' ? <button data-testid={`button-unassign-trip-${t.id}`} onClick={() => unassign.mutate({ tripId: t.id }, { onSuccess: invalidate })} className="rounded border border-border px-3 py-2 text-xs font-semibold hover:border-destructive hover:text-destructive">Unassign</button> : <div className="flex items-center gap-2"><select data-testid={`select-assign-trip-${t.id}`} defaultValue="" onChange={(e) => { if (e.target.value) assign.mutate({ tripId: t.id, data: { vehicleId: e.target.value } }, { onSuccess: invalidate }); }} className="h-9 max-w-[150px] rounded border border-input bg-background px-2 text-xs"><option value="" disabled>Assign vehicle</option>{(vehicles.data ?? []).filter((v) => v.connectionStatus === 'CONNECTED').map((v) => <option key={v.id} value={v.id}>{v.name}</option>)}</select></div>}</td></tr>)}</tbody></DataTable>}</Section></>; }

function LiveMap() { const vehicles = useListVehicles(); const located = (vehicles.data ?? []).filter((v) => v.lat !== null && v.lng !== null); const bounds = useMemo(() => { if (!located.length) return { minLat: 0, maxLat: 1, minLng: 0, maxLng: 1 }; const lats = located.map((v) => v.lat as number), lngs = located.map((v) => v.lng as number); return { minLat: Math.min(...lats), maxLat: Math.max(...lats), minLng: Math.min(...lngs), maxLng: Math.max(...lngs) }; }, [located]); const x = (lng: number) => 12 + ((lng - bounds.minLng) / Math.max(bounds.maxLng - bounds.minLng, .0001)) * 76; const y = (lat: number) => 86 - ((lat - bounds.minLat) / Math.max(bounds.maxLat - bounds.minLat, .0001)) * 72; return <><PageTitle eyebrow="Control room / live telemetry" title="Mine map" detail="Authenticated GPS positions only. The view updates when the telemetry stream broadcasts a change." action={<span className="flex items-center gap-2 rounded border border-emerald-700/20 bg-emerald-50 px-3 py-2 text-xs font-semibold text-emerald-700"><span className="h-2 w-2 animate-pulse rounded-full bg-emerald-500" /> Live positions</span>} /><div className="grid gap-6 xl:grid-cols-[1fr_300px]"><div className="scanline relative min-h-[560px] overflow-hidden rounded-md border border-[#28575a] bg-[#102d32] shadow-[var(--shadow-md)]"><div className="absolute inset-0 opacity-30" style={{ backgroundImage: 'linear-gradient(rgba(174,196,170,.15) 1px, transparent 1px), linear-gradient(90deg, rgba(174,196,170,.15) 1px, transparent 1px)', backgroundSize: '42px 42px' }} /><svg className="absolute inset-0 h-full w-full opacity-45" viewBox="0 0 100 100" preserveAspectRatio="none"><path d="M4 74 C18 63, 23 75, 35 55 S53 38, 63 53 S77 27, 96 23" fill="none" stroke="#d4a33e" strokeWidth=".5" strokeDasharray="2 2" /><path d="M8 20 C20 30, 35 24, 47 43 S70 68, 91 70" fill="none" stroke="#8ca9a0" strokeWidth=".35" /><path d="M15 82 L29 70 L48 77 L68 64 L83 79" fill="none" stroke="#8ca9a0" strokeWidth=".25" /></svg><div className="absolute left-5 top-5"><p className="mono text-[9px] uppercase tracking-[.2em] text-[#9ab9ae]">North sector / telemetry plane</p><p className="mt-2 condensed text-2xl font-semibold uppercase text-[#e5e0cd]">Live mine positions</p></div>{located.map((v) => <div key={v.id} data-testid={`map-vehicle-${v.id}`} className="absolute -translate-x-1/2 -translate-y-1/2" style={{ left: `${x(v.lng as number)}%`, top: `${y(v.lat as number)}%` }}><div className={cn('grid h-8 w-8 place-items-center rounded-full border-2 text-[10px] font-bold shadow-lg', v.operationalStatus === 'RUNNING' ? 'border-[#d4a33e] bg-[#d4a33e] text-[#102d32]' : 'border-[#8cb5a9] bg-[#20464a] text-[#e5e0cd]')}><Truck className="h-3.5 w-3.5" /></div><div className="mt-1 whitespace-nowrap rounded bg-[#0b2025]/85 px-1.5 py-0.5 text-[9px] text-[#e5e0cd]">{v.name}</div></div>)}{vehicles.isLoading && <div className="absolute inset-0 grid place-items-center text-[#e5e0cd]"><RefreshCw className="h-5 w-5 animate-spin" /></div>}{!vehicles.isLoading && !located.length && <div className="absolute inset-0 grid place-items-center"><div className="text-center text-[#bdcec2]"><MapIcon className="mx-auto mb-3 h-8 w-8" /><p className="text-sm">No authenticated GPS positions</p><p className="mt-1 text-xs opacity-70">Waiting for telemetry from the vehicle fleet.</p></div></div>}<div className="absolute bottom-5 left-5 flex gap-4 rounded bg-[#0b2025]/80 px-3 py-2 text-[10px] text-[#bdcec2]"><span><i className="mr-1 inline-block h-2 w-2 rounded-full bg-[#d4a33e]" />Running</span><span><i className="mr-1 inline-block h-2 w-2 rounded-full bg-[#8cb5a9]" />Other</span></div></div><Section title="Position register"><div className="space-y-3">{vehicles.isError ? <ErrorState retry={vehicles.refetch} /> : located.length ? located.map((v) => <div key={v.id} className="flex items-center justify-between border-b border-border pb-3 last:border-0 last:pb-0"><div><p className="text-sm font-semibold">{v.name}</p><p className="mono mt-1 text-[9px] text-muted-foreground">{(v.lat as number).toFixed(5)}, {(v.lng as number).toFixed(5)}</p></div><Badge tone={statusTone(v.connectionStatus)}>{titleCase(v.connectionStatus)}</Badge></div>) : <EmptyState icon={MapIcon} title="No coordinates" detail="The position register populates from server-side GPS values." />}</div></Section></div></>; }

function Incidents() { const incidents = useListIncidents(); const claim = useClaimIncidentResolution(); const qc = useQueryClient(); const [filter, setFilter] = useState<'ACTIVE' | 'RESOLVED'>('ACTIVE'); const [selected, setSelected] = useState<string | null>(null); const detail = useGetIncident(selected ?? '', { query: { enabled: !!selected, queryKey: getGetIncidentQueryKey(selected ?? '') } }); const rows = (incidents.data ?? []).filter((i) => i.status === filter); const claimIncident = (id: string) => claim.mutate({ incidentId: id }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getListIncidentsQueryKey() }); qc.invalidateQueries({ queryKey: getGetDashboardSummaryQueryKey() }); qc.invalidateQueries({ queryKey: getGetIncidentQueryKey(id) }); } }); return <><PageTitle eyebrow="Control room / safety desk" title="Incidents" detail="Claim resolution only after reviewing the backend-authored event. Active and resolved records remain visible for accountability." action={<div className="flex rounded border border-border bg-card p-1"><button data-testid="button-filter-active-incidents" onClick={() => setFilter('ACTIVE')} className={cn('rounded px-3 py-1.5 text-xs font-semibold', filter === 'ACTIVE' && 'bg-primary text-primary-foreground')}>Active</button><button data-testid="button-filter-resolved-incidents" onClick={() => setFilter('RESOLVED')} className={cn('rounded px-3 py-1.5 text-xs font-semibold', filter === 'RESOLVED' && 'bg-primary text-primary-foreground')}>Resolved</button></div>} />{claim.isError && <p className="mb-4 rounded border border-destructive/30 bg-red-50 p-3 text-xs text-destructive">Resolution could not be claimed. The incident remains unchanged.</p>}<div className="grid gap-6 xl:grid-cols-[1fr_320px]"><Section title={filter === 'ACTIVE' ? 'Active safety queue' : 'Resolved record'} meta={<span className="mono text-[10px] uppercase tracking-wider text-muted-foreground">{rows.length} records</span>}>{incidents.isLoading ? <SkeletonRows count={5} /> : incidents.isError ? <ErrorState retry={incidents.refetch} /> : !rows.length ? <EmptyState icon={filter === 'ACTIVE' ? ShieldCheck : CheckCircle2} title={filter === 'ACTIVE' ? 'No active incidents' : 'No resolved incidents'} detail={filter === 'ACTIVE' ? 'The active safety queue is clear.' : 'Resolved events will remain available here.'} /> : <div className="space-y-2">{rows.map((i) => <div key={i.id} className={cn('rounded border p-4', selected === i.id ? 'border-primary bg-primary/[.03]' : 'border-border')}><IncidentRow incident={i} onInspect={() => setSelected(i.id)} onClaim={filter === 'ACTIVE' ? () => claimIncident(i.id) : undefined} />{filter === 'RESOLVED' && i.resolvedAt && <p className="mt-3 border-t border-border pt-3 text-[10px] text-muted-foreground">Resolved {formatTime(i.resolvedAt)}</p>}</div>)}</div>}</Section><Section title="Incident detail" meta={selected && <button data-testid="button-close-incident-detail" onClick={() => setSelected(null)}><X className="h-4 w-4" /></button>}>{!selected ? <EmptyState icon={CircleAlert} title="Select an incident" detail="Inspect the complete backend record before claiming a resolution." /> : detail.isLoading ? <SkeletonRows count={4} /> : detail.isError ? <ErrorState retry={detail.refetch} /> : detail.data ? <div className="space-y-4"><div><p className="mono text-xs font-semibold">{detail.data.id}</p><h3 className="mt-2 text-lg font-semibold">{detail.data.vehicleName}</h3></div><div className="space-y-3 text-xs"><div className="flex justify-between border-b border-border pb-2"><span className="text-muted-foreground">Type</span><span className="font-semibold">{titleCase(detail.data.type)}</span></div><div className="flex justify-between border-b border-border pb-2"><span className="text-muted-foreground">Severity</span><Badge tone={statusTone(detail.data.severity)}>{detail.data.severity}</Badge></div><div className="flex justify-between border-b border-border pb-2"><span className="text-muted-foreground">Created</span><span className="mono">{formatTime(detail.data.createdAt)}</span></div></div><p className="rounded bg-secondary p-3 text-xs leading-5">{detail.data.message}</p></div> : null}</Section></div></>; }

function Safety() { const safety = useGetSafetyOverview(); const rows = safety.data ?? []; const unsafe = rows.filter((r) => r.safetyStatus === 'UNSAFE').length; return <><PageTitle eyebrow="Control room / safety monitoring" title="Safety monitor" detail="Backend-derived readiness across GPS, sensors, cameras, and vehicle safety status. No client-side assumptions." action={<div className={cn('flex items-center gap-2 rounded border px-3 py-2 text-xs font-semibold', unsafe ? 'border-red-700/20 bg-red-50 text-destructive' : 'border-emerald-700/20 bg-emerald-50 text-emerald-700')}><ShieldCheck className="h-4 w-4" /> {unsafe ? `${unsafe} unsafe` : 'All clear'}</div>} /><Section title="Safety matrix" meta={<span className="mono text-[10px] uppercase tracking-wider text-muted-foreground">{rows.length} vehicles</span>}>{safety.isLoading ? <SkeletonRows count={6} /> : safety.isError ? <ErrorState retry={safety.refetch} /> : !rows.length ? <EmptyState icon={ShieldCheck} title="No safety rows" detail="Backend safety evaluations will appear when vehicles are available." /> : <DataTable><thead><tr className="border-b border-border bg-secondary/60 text-[10px] uppercase tracking-[.14em] text-muted-foreground"><th className="px-5 py-3">Vehicle</th><th className="px-5 py-3">GPS</th><th className="px-5 py-3">Sensors</th><th className="px-5 py-3">Camera</th><th className="px-5 py-3">Overall</th></tr></thead><tbody>{rows.map((r) => <SafetyTableRow key={r.vehicle.id} row={r} />)}</tbody></DataTable>}</Section></>; }
function SafetyTableRow({ row }: { row: SafetyRow }) { const signal = (healthy: boolean) => <span className={cn('inline-flex items-center gap-2 text-xs font-semibold', healthy ? 'text-emerald-700' : 'text-destructive')}><span className={cn('h-2 w-2 rounded-full', healthy ? 'bg-emerald-500' : 'bg-destructive')} />{healthy ? 'Healthy' : 'Fault'}</span>; return <tr data-testid={`row-safety-${row.vehicle.id}`} className="border-b border-border last:border-0"><td className="px-5 py-4"><p className="font-semibold">{row.vehicle.name}</p><p className="mono text-[10px] text-muted-foreground">{row.vehicle.id}</p></td><td className="px-5 py-4">{signal(row.gpsHealthy)}</td><td className="px-5 py-4">{signal(row.sensorHealthy)}</td><td className="px-5 py-4">{signal(row.cameraHealthy)}</td><td className="px-5 py-4"><Badge tone={statusTone(row.safetyStatus)}>{titleCase(row.safetyStatus)}</Badge></td></tr>; }
function SystemStatus() { const status = useGetSystemStatus(); const rows = status.data ? [['Backend', status.data.backend], ['Database', status.data.database], ['WebSocket', status.data.websocket], ['Authentication', status.data.authentication]] : []; return <><PageTitle eyebrow="Admin / system status" title="System status" detail="Backend-reported service health and operational counters." action={<span className={cn('flex items-center gap-2 rounded border px-3 py-2 text-xs font-semibold', status.isError ? 'border-red-700/20 bg-red-50 text-destructive' : 'border-emerald-700/20 bg-emerald-50 text-emerald-700')}><span className="h-2 w-2 rounded-full bg-current" /> {status.isError ? 'Unavailable' : 'Connected'}</span>} /><div className="grid gap-4 sm:grid-cols-3"><StatCard label="Registered vehicles" value={status.data?.registeredVehicles ?? '—'} detail="Backend registry" icon={Truck} /><StatCard label="Connected devices" value={status.data?.connectedDevices ?? '—'} detail="Authenticated telemetry" icon={Cpu} tone="green" /><StatCard label="Active incidents" value={status.data?.activeIncidents ?? '—'} detail="Safety queue" icon={AlertTriangle} tone={status.data?.activeIncidents ? 'red' : 'amber'} /></div><Section title="Service health" className="mt-6">{status.isLoading ? <SkeletonRows count={4} /> : status.isError ? <ErrorState retry={status.refetch} message="Unable to connect to Mine Vision-X system status." /> : <div className="space-y-3">{rows.map(([label, value]) => <div key={label} className="flex items-center justify-between border-b border-border pb-3 last:border-0 last:pb-0"><span className="text-sm font-semibold">{label}</span><Badge tone={value === 'healthy' || value === 'ready' ? 'good' : 'critical'}>{titleCase(value)}</Badge></div>)}</div>}</Section></>; }

function ProtectedRoute({ component: Component, role }: { component: () => ReactNode; role?: 'ADMIN' | 'CONTROL_ROOM' }) { return <AuthGate><RolePage component={Component} role={role} /></AuthGate>; }
function RolePage({ component: Component, role }: { component: () => ReactNode; role?: 'ADMIN' | 'CONTROL_ROOM' }) { const user = useGetCurrentUser(); const [, setLocation] = useLocation(); useEffect(() => { if (user.data && role && user.data.role !== role) setLocation(user.data.role === 'ADMIN' ? '/admin' : '/control-room'); }, [role, setLocation, user.data]); if (!user.data) return null; return <Component />; }
function NotFoundPage() { return <div className="grid min-h-[100dvh] place-items-center bg-background p-6"><div className="text-center"><p className="mono text-[10px] uppercase tracking-[.2em] text-primary">MV-X / 404</p><h1 className="condensed mt-3 text-6xl font-semibold uppercase">Not found</h1><p className="mt-3 text-sm text-muted-foreground">This operational view does not exist.</p><Link href="/login" className="mt-6 inline-flex items-center gap-2 rounded bg-primary px-4 py-2 text-sm font-semibold text-primary-foreground"><ArrowLeft className="h-4 w-4" /> Return to sign-in</Link></div></div>; }

function Router() { return <Switch><Route path="/login" component={Login} /><Route path="/admin" component={() => <ProtectedRoute role="ADMIN" component={AdminOverview} />} /><Route path="/admin/vehicles" component={() => <ProtectedRoute role="ADMIN" component={VehicleRegistration} />} /><Route path="/admin/hardware" component={() => <ProtectedRoute role="ADMIN" component={Hardware} />} /><Route path="/admin/users" component={() => <ProtectedRoute role="ADMIN" component={UsersPage} />} /><Route path="/admin/incidents" component={() => <ProtectedRoute role="ADMIN" component={Incidents} />} /><Route path="/admin/system-status" component={() => <ProtectedRoute role="ADMIN" component={SystemStatus} />} /><Route path="/control-room" component={() => <ProtectedRoute role="CONTROL_ROOM" component={ControlDashboard} />} /><Route path="/control-room/fleet" component={() => <ProtectedRoute role="CONTROL_ROOM" component={FleetOverview} />} /><Route path="/control-room/fleet/vehicles" component={() => <ProtectedRoute role="CONTROL_ROOM" component={FleetVehicles} />} /><Route path="/control-room/fleet/speed-limits" component={() => <ProtectedRoute role="CONTROL_ROOM" component={SpeedLimits} />} /><Route path="/control-room/fleet/trips" component={() => <ProtectedRoute role="CONTROL_ROOM" component={Trips} />} /><Route path="/control-room/live-monitoring" component={() => <ProtectedRoute role="CONTROL_ROOM" component={FleetVehicles} />} /><Route path="/control-room/map" component={() => <ProtectedRoute role="CONTROL_ROOM" component={LiveMap} />} /><Route path="/control-room/incidents" component={() => <ProtectedRoute role="CONTROL_ROOM" component={Incidents} />} /><Route path="/control-room/safety" component={() => <ProtectedRoute role="CONTROL_ROOM" component={Safety} />} /><Route path="/" component={() => localStorage.getItem('mine-vision-token') ? <RedirectHome /> : <Login />} /><Route component={NotFoundPage} /></Switch>; }
function RedirectHome() { const [, setLocation] = useLocation(); const user = useGetCurrentUser(); useEffect(() => { if (user.data) setLocation(user.data.role === 'ADMIN' ? '/admin' : '/control-room'); else if (user.isError) setLocation('/login'); }, [user.data, user.isError, setLocation]); return <div className="grid min-h-[100dvh] place-items-center"><RefreshCw className="h-5 w-5 animate-spin text-primary" /></div>; }
function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><ErrorBoundary><Router /></ErrorBoundary></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>; }
export default App;